static int Verdopple(int x)
{
    return x * 2;
}

Func<int, int> f = Verdopple;   // Methode merken – ohne ()!
Console.WriteLine(f(5));
Console.WriteLine(f(21));
// Ausgabe:
// 10
// 42

Func<int, int> quadrat = x => x * x;
Func<int, int, int> plus = (a, b) => a + b;
Func<string, bool> istLang = s => s.Length > 5;
Action<string> gruesse = name => Console.WriteLine($"Hallo {name}!");

Console.WriteLine(quadrat(4));
Console.WriteLine(plus(3, 4));
Console.WriteLine(istLang("Schule"));
gruesse("Mia");
// Ausgabe:
// 16
// 7
// True
// Hallo Mia!

Func<int, string> bewerte = punkte =>
{
    if (punkte >= 50)
        return "bestanden";
    return "nicht bestanden";
};
Console.WriteLine(bewerte(73));
// Ausgabe: bestanden

static List<int> Filtere(List<int> liste, Func<int, bool> bedingung)
{
    var ergebnis = new List<int>();
    foreach (int x in liste)
    {
        if (bedingung(x))
            ergebnis.Add(x);
    }
    return ergebnis;
}

var zahlen = new List<int> { 4, 11, 8, 3, 15 };
Console.WriteLine(string.Join(" ", Filtere(zahlen, x => x > 5)));
Console.WriteLine(string.Join(" ", Filtere(zahlen, x => x % 2 == 0)));

zahlen.RemoveAll(x => x < 5);
zahlen.ForEach(x => Console.Write(x + ";"));
// Ausgabe:
// 11 8 15
// 4 8
// 11;8;15;

int grenze = 10;
Func<int, bool> zuGross = x => x > grenze;
Console.WriteLine(zuGross(15));
grenze = 20;
Console.WriteLine(zuGross(15));
// Ausgabe:
// True
// False

